const payload = msg.payload || {};
const chatId = payload.chatId || payload.chatid || payload.message?.chat?.id;
const text = String(payload.content || payload.text || payload.message?.text || '').trim();

if (!chatId) {
    node.warn('Mensagem sem chatId recebida do Telegram.');
    return [null, null];
}

const stateKey = `awaitingCpf:${chatId}`;

function reply(content) {
    return {
        payload: {
            chatId,
            type: 'message',
            content
        }
    };
}

function onlyDigits(value) {
    return String(value || '').replace(/\D/g, '');
}

function isValidCpf(cpf) {
    cpf = onlyDigits(cpf);
    if (cpf.length !== 11 || /^(\d)\1{10}$/.test(cpf)) return false;

    let sum = 0;
    for (let i = 0; i < 9; i++) sum += Number(cpf[i]) * (10 - i);
    let check = 11 - (sum % 11);
    if (check >= 10) check = 0;
    if (check !== Number(cpf[9])) return false;

    sum = 0;
    for (let i = 0; i < 10; i++) sum += Number(cpf[i]) * (11 - i);
    check = 11 - (sum % 11);
    if (check >= 10) check = 0;
    return check === Number(cpf[10]);
}

function buildWatsonMessage() {
    const apiKey = env.get('WATSON_API_KEY');
    const assistantId = env.get('WATSON_ASSISTANT_ID');
    const serviceUrl = String(env.get('WATSON_SERVICE_URL') || '').replace(/\/$/, '');
    const version = env.get('WATSON_VERSION') || '2024-08-25';

    msg.chatId = chatId;
    msg.userText = text || '/start';
    msg.watsonConfigured = Boolean(apiKey && assistantId && serviceUrl);
    msg.fallbackReply = 'Em que posso ajudar';

    if (msg.watsonConfigured) {
        msg.method = 'POST';
        msg.url = `${serviceUrl}/v2/assistants/${assistantId}/message?version=${version}`;
        msg.headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'Authorization': `Basic ${Buffer.from(`apikey:${apiKey}`).toString('base64')}`
        };
        msg.payload = {
            input: {
                message_type: 'text',
                text: msg.userText
            },
            context: {
                global: {
                    system: {
                        user_id: String(chatId)
                    }
                }
            }
        };
    }

    return msg;
}

if (!text || text === '/start') {
    flow.set(stateKey, true);
    return [null, buildWatsonMessage()];
}

if (flow.get(stateKey)) {
    const cpf = onlyDigits(text);

    if (cpf.length !== 11) {
        return [null, reply('CPF invalido. Envie 11 digitos, com ou sem pontuacao.')];
    }

    if (!isValidCpf(cpf)) {
        return [null, reply('CPF invalido. Confira os digitos e tente novamente.')];
    }

    msg.chatId = chatId;
    msg.cpf = cpf;
    msg.topic = `SELECT cpf, nome, status, plano, atualizado_em FROM clientes WHERE cpf = '${cpf}' LIMIT 1`;
    flow.set(stateKey, false);
    return [msg, null];
}

flow.set(stateKey, true);
return [null, buildWatsonMessage()];

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const cpf = String(msg.cpf || '').replace(/\D/g, '');
const maskedCpf = cpf.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4');

let content;
if (rows.length === 0) {
    content = `Nao encontrei cadastro para o CPF ${maskedCpf}.`;
} else {
    const cliente = rows[0];
    content = [
        `Cadastro encontrado para ${maskedCpf}:`,
        `Nome: ${cliente.nome}`,
        `Status: ${cliente.status}`,
        `Plano: ${cliente.plano || 'nao informado'}`,
        `Atualizado em: ${cliente.atualizado_em}`
    ].join('\n');
}

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content
};
return msg;

const generic = msg.payload?.output?.generic || [];
const texts = generic
    .filter(item => item.response_type === 'text' && item.text)
    .map(item => item.text.trim())
    .filter(Boolean);

let watsonText = texts.join('\n');
if (!watsonText || msg.statusCode >= 300) {
    watsonText = msg.fallbackReply || 'Em que posso ajudar';
}

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: `${watsonText}\n\nDigite seu CPF para consulta.`
};
return msg;

msg.payload = {
    chatId: msg.chatId,
    type: 'message',
    content: `${msg.fallbackReply || 'Em que posso ajudar'}\n\nDigite seu CPF para consulta.`
};
return msg;
